mapper.select:
SELECT m.id, m.author_id, m.content, m.visibility, m.like_count, m.comment_count, m.status, m.created_at, m.deleted_at FROM im_moment m LEFT JOIN im_moment_setting s ON s.user_id = m.author_id WHERE m.deleted_at IS NULL AND m.id < #{cursor} AND (m.author_id = #{viewerId} OR m.status = 0) AND m.author_id IN (SELECT f.friend_id FROM im_friend f WHERE f.user_id = #{viewerId} UNION ALL SELECT #{viewerId})
AND m.author_id = #{authorId}
AND (m.author_id = #{viewerId} OR (m.visibility <> 1 AND (m.visibility <> 2 OR EXISTS (SELECT 1 FROM im_moment_audience a WHERE a.moment_id = m.id AND a.user_id = #{viewerId} AND a.mode = 1)) AND NOT EXISTS (SELECT 1 FROM im_moment_audience a WHERE a.moment_id = m.id AND a.user_id = #{viewerId} AND a.mode = 2) AND (s.visible_days IS NULL OR s.visible_days = 0 OR TIMESTAMPADD(DAY, s.visible_days, m.created_at) >= #{now}))) ORDER BY m.id DESC LIMIT #{limit}
